      SUBROUTINE RECALLCC     RESETS MATRICES, PARAMETERS, AND LOGICAL VARIABLES TO VALUESC     AT BEGINNING OF SECTION WHERE FITTING OCCURSCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'COPS.CIN'      INCLUDE 'COSS.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'DATA2S.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM0F.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM1D.CIN'      INCLUDE 'ELM1E.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8B.CIN'      INCLUDE 'ELM8E.CIN'      INCLUDE 'ELM9.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM20.CIN'      INCLUDE 'ELM22A.CIN'      INCLUDE 'ELM24B.CIN'      INCLUDE 'ELM24C.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'ELM31B.CIN'      INCLUDE 'ELS0B.CIN'      INCLUDE 'ELS1A.CIN'      INCLUDE 'ELS1D.CIN'      INCLUDE 'ELS7B.CIN'      INCLUDE 'ELS8A.CIN'      INCLUDE 'ELS8B.CIN'      INCLUDE 'ELS8C.CIN'      INCLUDE 'ELS10E.CIN'      INCLUDE 'ELS13A.CIN'      INCLUDE 'ELS16A.CIN'      INCLUDE 'ELS16B.CIN'      INCLUDE 'ELS20.CIN'      INCLUDE 'ELS22A.CIN'      INCLUDE 'ELS24A.CIN'      INCLUDE 'ELS24B.CIN'      INCLUDE 'ELS24C.CIN'      INCLUDE 'ELS26B.CIN'      INCLUDE 'ELS31.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETAP.CIN'      INCLUDE 'ETAPS.CIN'      INCLUDE 'ETASC.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'IOUNIT.CIN'      INCLUDE 'OC.CIN'      INCLUDE 'OCP.CIN'      INCLUDE 'OCPS.CIN'      INCLUDE 'OCS.CIN'      INCLUDE 'RCP.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'SEEDS.CIN'      INCLUDE 'SI.CIN'      INCLUDE 'SIS.CIN'      INCLUDE 'SVP.CIN'CC     LOCAL VARIABLESC      INTEGER          IPP, J, K, K1, K2, NC-------------------------------------------------------------------------------C      NUM = NUMS      NDIF = NDIFS      LC = LCS      TOTROT = TOTRTS      DO 5 N = 1, NV3      LCV(N) = 0      RVP(N) = .FALSE.      R2VP(N) = .FALSE.      SVP(N) = .FALSE.      CVP(N) = .FALSE.      EVP(N) = .FALSE.      OVP(N) = .FALSE.    5 CONTINUE      CALL MRECC      DO 110 J = 1, 6      DO 110 K = 1, 6  110 SI(J,K) = SIS(J,K)      DO 120 J = 1, 6  120 CO(J) = COSS(J)      RI = RIS      PSIXO = PSIXOS      PSIYO = PSIYOS      SOFA = SOFAS      DO 130 J = 1, 6  130 COF(J) = COFS(J)      RECENT = .FALSE.      DO 135 J = 1, 6  135 ETA(J) = ETAS(J)      RAY = RAYS      NMARK = NMRKS      NMARKS = NMRKSS      MKG = MKGS      NDIFM = NDIFMS      DO 137 J = 1, 4  137 OCP(J) = OCPS(J)C      IF (.NOT. ALIGN .AND. .NOT. LAY) GO TO 200      DO 140 J = 1, 4      DO 140 K1 = 1, 3      DO 140 K2 = 1, 3  140 O(J,K1,K2) = OS(J,K1,K2)      DO 150 J = 1, 4      DO 150 K = 1, 3  150 X0(J,K) = X0S(J,K)      RORC = RORCS      DO 160 J = 1, 6  160 VM(J) = VMS(J)C  200 NC = 0      NV1 = 0      LAY = LAYS      R1P = R1PS      FOTILT = FOTLTS      SM = SMS      PREF = PREFSC      IF (.NOT. ALIGN) GO TO 250      DO 210 J = 1, 3      DO 210 K1 = 1, 6      DO 210 K2 = 1, 6      SIOL(J,K1,K2) = SIOLS(J,K1,K2)  210 RCO(J,K1,K2) = RCOS(J,K1,K2)      DO 220 J = 1, 3      DO 220 K = 1, 6  220 COLD(J,K) = COLDS(J,K)      DO 230 J = 1, 6      DO 230 K = 1, 6  230 R2O(J,K) = R2OS(J,K)      DO 240 J = 1, 3      SPO(J) = SPOS(J)  240 RCPO(J) = RCPOS(J)      R2PO = R2POSC  250 ATWORK = ATWSC      DO 260 J = 1, 20      REG(J) = REGS(J)  260 LREG(J) = LREGS(J)      IP = IPS      IF (IP .LT. 0 .OR. IP .GT. 4) THEN        WRITE (NOUT,9005) IP 9005   FORMAT (' IN RECALL, IP = ',I5)        FLUSHL = .TRUE.        GO TO 500      ENDIF      IF (IP .NE. 0) THEN        DO 265 IPP = 1, IP        IC(IPP) = ICS(IPP)  265   IS(IPP) = ISS(IPP)      ENDIF      NDLEV = NDLEVS      IF (NDLEV .GT. 0) THEN        DO 280 N = 1, NDLEV        NDC(N) = NDCS(N)        NDS(N) = NDSS(N)  280   NDN(N) = NDNS(N)      ENDIFC  300 DO 305 J = 1, 4  305 PRAN2(J) = PRAN2S(J)      PRAN3 = PRAN3S      DO 310 J = 1, 15  310 PRAN4(J) = PRAN4S(J)      DO 320 J = 1, 5  320 PRAN5(J) = PRAN5S(J)      DO 330 J = 1, 6  330 PRAN7(J) = PRAN7S(J)      DO 340 J = 1, 4  340 PRAN11(J) = PRN11S(J)      DO 350 J = 1, 4  350 PRAN18(J) = PRN18S(J)      DO 360 J = 1, 3  360 PRAN19(J) = PRN19S(J)      PRAN20 = PRN20S      DO 370 J = 1, 4  370 PRAN25(J) = PRN25S(J)      DO 380 J = 1, 9  380 PRAN28(J) = PRN28S(J)      DO 390 J = 1, 5  390 PRAN34(J) = PRN34S(J)      DO 400 J = 1, 6  400 PRAN43(J) = PRN43S(J)C      BDBI = BDBIS      APBI(1) = APBIS(1)      APBI(2) = APBIS(2)      LAYKI = LAYKIS      LAYLI = LAYLIS      LAYXI = LAYXIS      RAB1I = RAB1IS      RAB2I = RAB2IS      RMPSI = RMPSIS      RNMSI = RNMSIS      VRNI = VRNIS      NPNI = NPNIS      BDBPI = BDBPISC      CALL RANSET(ISEEDS)  500 RETURN      END